use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl CompilerLayer { fn from_path (path : & Path) -> Self { let path_str = path . to_string_lossy () . to_lowercase () ; if path_str . contains ("ast") || path_str . contains ("syntax") { CompilerLayer :: AST } else if path_str . contains ("hir") && ! path_str . contains ("thir") { CompilerLayer :: HIR } else if path_str . contains ("mir") { CompilerLayer :: MIR } else if path_str . contains ("thir") { CompilerLayer :: THIR } else if path_str . contains ("parse") || path_str . contains ("lexer") { CompilerLayer :: Parser } else if path_str . contains ("resolve") || path_str . contains ("name") { CompilerLayer :: Resolve } else if path_str . contains ("typeck") || path_str . contains ("type") { CompilerLayer :: TypeCk } else if path_str . contains ("codegen") || path_str . contains ("llvm") { CompilerLayer :: Codegen } else if path_str . contains ("lint") { CompilerLayer :: Lint } else if path_str . contains ("macro") || path_str . contains ("expand") { CompilerLayer :: Macro } else { CompilerLayer :: Other (path . parent () . and_then (| p | p . file_name ()) . and_then (| n | n . to_str ()) . unwrap_or ("unknown") . to_string ()) } } fn emoji (& self) -> & 'static str { match self { CompilerLayer :: AST => "🌲" , CompilerLayer :: HIR => "🌳" , CompilerLayer :: MIR => "🔬" , CompilerLayer :: THIR => "🏷️" , CompilerLayer :: Parser => "📖" , CompilerLayer :: Resolve => "🔍" , CompilerLayer :: TypeCk => "✅" , CompilerLayer :: Codegen => "⚙️" , CompilerLayer :: Lint => "🔍" , CompilerLayer :: Macro => "🎭" , CompilerLayer :: Other (_) => "📁" , } } }
}